using System;
using System.Linq;
using System.Security.Cryptography;
using CashflowChains.Economy;
using CashflowChains.Engagement;
namespace CashflowChains.Empire {
 public sealed partial class EmpireEngine {
  public CommandReceipt OpenInvestorRewards(long now)=>Command("investor-rewards-v1","investor-v1","investor-rewards","initialize",now,(a,t)=>{if(a.City==null||a.City.Region<2||config.Investor==null)throw new InvalidOperationException("Enter the established city first");a.Investor=new InvestorState{StartedAt=now};});
  InvestorState RequiredInvestor(EmpireAccount a)=>a.Investor??throw new InvalidOperationException("Investor rewards are not open");
  static void InvestorGrant(EmpireAccount a,EconomyTransaction t,string id,string kind,int index,int season,long day,ItemAmount[] items){foreach(var item in items)t.Grant(item.ItemId,item.Quantity);a.Investor.Claims.Add(new InvestorClaim{Id=id,Kind=kind,Index=index,Season=season,Day=day,Items=items.Select(x=>new ItemAmount(x.ItemId,x.Quantity)).ToArray()});}
  public CommandReceipt ClaimInvestorDaily(long now){lock(gate){var s=RequiredInvestor(state);long day=now/86400;string id="investor-daily:"+day;return Command(id,day.ToString(),"investor-rewards","daily",now,(a,t)=>{var current=RequiredInvestor(a);int index=current.Claims.Count(x=>x.Kind=="daily")%config.Investor.Daily.Length;InvestorGrant(a,t,id,"daily",index,current.Season(config.Investor,now),day,config.Investor.Daily[index].Free);});}}
  public CommandReceipt ClaimInvestorDailyPremium(long freeDay,long now){string id="investor-daily-premium:"+freeDay;return Command(id,freeDay.ToString(),"investor-rewards","daily-premium",now,(a,t)=>{var s=RequiredInvestor(a);var free=s.Claims.SingleOrDefault(x=>x.Kind=="daily"&&x.Day==freeDay)??throw new InvalidOperationException("Claim that free daily reward first");if(!s.Owns("daily",free.Season,config.Investor))throw new InvalidOperationException("Investor Club ownership must be verified");InvestorGrant(a,t,id,"daily-premium",free.Index,free.Season,now/86400,config.Investor.Daily[free.Index].Premium);});}
  public CommandReceipt ClaimInvestorMilestone(int index,bool premium,long now){if(index<0||index>=config.Investor.Milestones.Length)throw new ArgumentException("Unknown milestone");string id="investor-milestone:"+index+":"+premium;return Command(id,index+":"+premium,"investor-rewards","milestone",now,(a,t)=>{var s=RequiredInvestor(a);if(a.City.CareerStage<=index)throw new InvalidOperationException("Complete this real investor milestone first");if(premium&&!s.Owns("growth",0,config.Investor))throw new InvalidOperationException("Growth Fund ownership must be verified");var pair=config.Investor.Milestones[index];InvestorGrant(a,t,id,premium?"milestone-premium":"milestone",index,s.Season(config.Investor,now),now/86400,premium?pair.Premium:pair.Free);});}
  public CommandReceipt ClaimInvestorSeason(int season,int tier,bool premium,long now){if(tier<0||tier>=config.Investor.Season.Length)throw new ArgumentException("Unknown season tier");string id="investor-season:"+season+":"+tier+":"+premium;return Command(id,season+":"+tier+":"+premium,"investor-rewards","season",now,(a,t)=>{var s=RequiredInvestor(a);if(season<0||season>s.Season(config.Investor,now)||s.Xp(season)<(tier+1)*config.Investor.TierXp)throw new InvalidOperationException("Earn this tier through your businesses first");if(premium&&!s.Owns("season",season,config.Investor))throw new InvalidOperationException("This season pass must be verified");var pair=config.Investor.Season[tier];InvestorGrant(a,t,id,premium?"season-premium":"season",tier,season,now/86400,premium?pair.Premium:pair.Free);});}
  public CommandReceipt OpenInvestorChest(string id,long now)=>Command(id,"bronze-v1","investor-rewards","earned-chest",now,(a,t)=>{var s=RequiredInvestor(a);var balance=a.Economy.Balances.SingleOrDefault(x=>x.ItemId=="CHEST:bronze");if(balance==null||balance.Earned<1)throw new InvalidOperationException("An earned supply chest is required. Paid random rewards require the online authority.");t.Spend("CHEST:bronze",1);int index=config.Investor.BronzeIndex(InvestorRandom());InvestorGrant(a,t,id,"chest",index,s.Season(config.Investor,now),now/86400,config.Investor.Bronze[index].Items);});
  static int InvestorRandom(){using(var rng=RandomNumberGenerator.Create()){var bytes=new byte[4];uint value;do{rng.GetBytes(bytes);value=BitConverter.ToUInt32(bytes,0);}while(value>=4294960000u);return (int)(value%10000);}}
  // Trusted fulfillment boundary only. Never expose this command to the public client command enum.
  // A platform/server verifier must bind account, purchased state, product, transaction and season first.
  public CommandReceipt FulfillVerifiedInvestorPurchase(string tokenHash,string product,int season,long now){if(tokenHash==null||tokenHash.Length!=64||tokenHash.Any(x=>!Uri.IsHexDigit(x)))throw new ArgumentException("Invalid verified purchase reference");string id="investor-verified-purchase:"+tokenHash;return Command(id,product+":"+season,"investor-store","verified-purchase",now,(a,t)=>{var s=RequiredInvestor(a);var p=config.Investor.Product(product);if(a.City.Properties.Count(x=>x.Level>0)<p.MinimumAssets||season!=s.Season(config.Investor,now))throw new InvalidOperationException("Product is not eligible");if(!p.Consumable&&s.Purchases.Any(x=>x.Product==product)||p.Family=="season"&&s.Owns("season",season,config.Investor))throw new InvalidOperationException("Already owned");foreach(var item in p.Items)t.Grant(item.ItemId,item.Quantity,BalanceOrigin.Purchased);s.Purchases.Add(new InvestorPurchase{Id=id,Product=product,Season=season,Day=now/86400});});}
 }
}
